/* g++ dumps ~90 lines citing stl_algo.h, but the map is:
   In file included from /usr/include/c++/13/algorithm ...
   required from here
   error: no match for 'operator<'
   (operand types are 'const Ponto' and 'const Ponto')
   Translation: Ponto has no operator<; define one or pass
   a comparator to sort. The error is YOURS, not the header's. */

struct No {
    char op;              // 0 when it is a numeric leaf
    int valor;
    No *esq, *dir;
};

int avaliar(const No* n) {
    if (n->op == 0) return n->valor;      // leaf: worth itself
    int e = avaliar(n->esq);              // 1: resolve the left
    int d = avaliar(n->dir);              // 2: resolve the right
    switch (n->op) {                      // 3: apply the operator
        case '+': return e + d;
        case '-': return e - d;
        case '*': return e * d;
        default:  return e / d;
    }
}

