// mat.h
#ifndef MAT_H
#define MAT_H
double media(const int* v, int n);
int maior(const int* v, int n);
#endif

// mat.cpp
#include "mat.h"
double media(const int* v, int n) {
    long soma = 0;
    for (int i = 0; i < n; i++) soma += v[i];
    return n ? (double)soma / n : 0.0;
}
int maior(const int* v, int n) {
    int m = v[0];
    for (int i = 1; i < n; i++) if (v[i] > m) m = v[i];
    return m;
}

// main.cpp
#include <cstdio>
#include "mat.h"
int main() {
    int notas[] = {70, 85, 90, 60, 100};
    printf("media %.1f maior %d\n", media(notas, 5), maior(notas, 5));
}
